      font-style: normal;
      font-weight: 500;
      line-height: 20px;
    }

    .toggle-button:hover {
      background: ${unsafeCSSVarV2('layer/background/hoverOverlay')};
    }

    .toggle-button.active {
      background: ${unsafeCSSVarV2('segment/button')};
      box-shadow:
        var(--Shadow-buttonShadow-1-x, 0px) var(--Shadow-buttonShadow-1-y, 0px)
          var(--Shadow-buttonShadow-1-blur, 1px) 0px
          var(--Shadow-buttonShadow-1-color, rgba(0, 0, 0, 0.12)),
        var(--Shadow-buttonShadow-2-x, 0px) var(--Shadow-buttonShadow-2-y, 1px)
          var(--Shadow-buttonShadow-2-blur, 5px) 0px
          var(--Shadow-buttonShadow-2-color, rgba(0, 0, 0, 0.12));
    }
  `;

  private readonly _toggle = (value: boolean) => {
    this.blockComponent.setPreviewState(value);

    const std = this.blockComponent.std;
    const mode = std.getOptional(DocModeProvider)?.getEditorMode() ?? 'page';
    const telemetryService = std.getOptional(TelemetryProvider);
    if (!telemetryService) return;
    telemetryService.track('htmlBlockTogglePreview', {
      page: mode,
      segment: 'code block',
      module: 'code toolbar container',
      control: 'preview toggle button',
    });
  };

  get preview() {
    return this.blockComponent.preview$.value;
  }

  override render() {
    const lang = this.blockComponent.model.props.language$.value ?? '';
    const previewContext = this.blockComponent.std.getOptional(
      CodeBlockPreviewIdentifier(lang)
    );
    if (!previewContext) return nothing;

    return html`
      <div class="preview-toggle-container">
        <div
          class=${classMap({
            'toggle-button': true,
            active: !this.preview,
          })}
          @click=${() => this._toggle(false)}
        >
          Code
        </div>
        <div
          class=${classMap({
            'toggle-button': true,
            active: this.preview,
          })}
          @click=${() => this._toggle(true)}
        >
          Preview
        </div>
      </div>
    `;
  }

  @property({ attribute: false })
  accessor blockComponent!: CodeBlockComponent;
}

import React from 'react'

import { cmExtensions$, diffMarkdown$, readOnlyDiff$ } from '.'
import { markdown$, markdownSourceEditorValue$, onBlur$, readOnly$ } from '../core'

import { MergeView } from '@codemirror/merge'
import { EditorState } from '@codemirror/state'
import { EditorView } from '@codemirror/view'
import { COMMON_STATE_CONFIG_EXTENSIONS } from './SourceEditor'
import { useCellValue, useCellValues, usePublisher, useRealm } from '@mdxeditor/gurx'

function setContent(view: EditorView | undefined, content: string) {
  if (view !== undefined) {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: content } })
  }
}

export const DiffViewer: React.FC = () => {
  const realm = useRealm()
  const [newMarkdown, oldMarkdown, readOnly, readOnlyDiff] = useCellValues(markdown$, diffMarkdown$, readOnly$, readOnlyDiff$)
  const onUpdate = usePublisher(markdownSourceEditorValue$)
  const elRef = React.useRef<HTMLDivElement | null>(null)
  const cmMergeViewRef = React.useRef<MergeView | null>(null)
  const cmExtensions = useCellValue(cmExtensions$)
  const triggerOnBlur = usePublisher(onBlur$)

  React.useEffect(() => {
    return realm.sub(diffMarkdown$, (newDiffMarkdown) => {
      setContent(cmMergeViewRef.current?.a, newDiffMarkdown)
    })
  }, [realm])

  React.useEffect(() => {
    return realm.sub(markdown$, (newMarkdown) => {
      setContent(cmMergeViewRef.current?.b, newMarkdown)
    })
  }, [realm])

  React.useEffect(() => {
    const isReadOnly = readOnly || readOnlyDiff

    const revertParams = isReadOnly
      ? ({
          renderRevertControl: undefined,
          revertControls: undefined
        } as const)
      : ({
          renderRevertControl: () => {
            const el = document.createElement('button')
            el.classList.add('cm-merge-revert')
            el.appendChild(document.createTextNode('\u2B95'))
            return el
          },
          revertControls: 'a-to-b'
        } as const)

    cmMergeViewRef.current = new MergeView({
      ...revertParams,
      parent: elRef.current!,
      orientation: 'a-b',
      gutter: true,
      a: {
        doc: oldMarkdown,
        extensions: [...cmExtensions, ...COMMON_STATE_CONFIG_EXTENSIONS, EditorState.readOnly.of(true)]
      },
      b: {
        doc: newMarkdown,
        extensions: [
          ...cmExtensions,
          ...COMMON_STATE_CONFIG_EXTENSIONS,
          EditorState.readOnly.of(isReadOnly),
          EditorView.updateListener.of(({ state }) => {
            const md = state.doc.toString()
            onUpdate(md)
          }),
          EditorView.focusChangeEffect.of((_, focused) => {
            if (!focused) {
              triggerOnBlur(new FocusEvent('blur'))
            }
            return null
          })
        ]
      }
    })
    return () => {
      cmMergeViewRef.current?.destroy()
      cmMergeViewRef.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onUpdate, cmExtensions])

  return <div ref={elRef} className="mdxeditor-diff-editor" />
}

import { $createHeadingNode, $createQuoteNode } from '@lexical/rich-text'
import { useCellValue, usePublisher } from '@mdxeditor/gurx'
import { $createParagraphNode } from 'lexical'
import React, { JSX } from 'react'
import { BlockType, activePlugins$, convertSelectionToNode$, currentBlockType$, useTranslation } from '../../core'
import { allowedHeadingLevels$ } from '../../headings'
import { Select } from '.././primitives/select'

/**
 * A toolbar component that allows the user to change the block type of the current selection.
 * Supports paragraphs, headings and block quotes.
 * @group Toolbar Components
 */
export const BlockTypeSelect = () => {
  const convertSelectionToNode = usePublisher(convertSelectionToNode$)
  const currentBlockType = useCellValue(currentBlockType$)
  const activePlugins = useCellValue(activePlugins$)
  const hasQuote = activePlugins.includes('quote')
  const hasHeadings = activePlugins.includes('headings')
  const t = useTranslation()

  if (!hasQuote && !hasHeadings) {
    return null
  }
  const items: { label: string | JSX.Element; value: BlockType }[] = [
    { label: t('toolbar.blockTypes.paragraph', 'Paragraph'), value: 'paragraph' }
  ]

  if (hasQuote) {
    items.push({ label: t('toolbar.blockTypes.quote', 'Quote'), value: 'quote' })
  }

  if (hasHeadings) {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const allowedHeadingLevels = useCellValue(allowedHeadingLevels$)
    items.push(
      ...allowedHeadingLevels.map(
        (n) => ({ label: t('toolbar.blockTypes.heading', 'Heading {{level}}', { level: n }), value: `h${n}` }) as const
      )
    )
  }

  return (
    <Select<BlockType>
      value={currentBlockType}
      onChange={(blockType) => {
        switch (blockType) {
          case 'quote':
            convertSelectionToNode(() => $createQuoteNode())
            break
          case 'paragraph':
            convertSelectionToNode(() => $createParagraphNode())
            break
          case '':
            break
          default:
            if (blockType.startsWith('h')) {
              convertSelectionToNode(() => $createHeadingNode(blockType))
            } else {
              throw new Error(`Unknown block type: ${blockType}`)
            }
        }
      }}
      triggerTitle={t('toolbar.blockTypeSelect.selectBlockTypeTooltip', 'Select block type')}
      placeholder={t('toolbar.blockTypeSelect.placeholder', 'Block type')}
      items={items}
    />
  )
}

import { applyFormat$, currentFormat$, iconComponentFor$, useTranslation } from '../../core'
import { useCellValues, usePublisher } from '@mdxeditor/gurx'
import React from 'react'
import { FORMAT, IS_BOLD, IS_ITALIC, IS_STRIKETHROUGH, IS_SUBSCRIPT, IS_SUPERSCRIPT, IS_UNDERLINE } from '../../../FormatConstants'
import { ToggleSingleGroupWithItem } from '../primitives/toolbar'
import { TextFormatType } from 'lexical'
import styles from '../../../styles/ui.module.css'
import { IconKey } from '../../../defaultSvgIcons'

interface FormatButtonProps {
  format: FORMAT
  addTitle: string
  removeTitle: string
  icon: IconKey
  formatName: TextFormatType
}

const FormatButton: React.FC<FormatButtonProps> = ({ format, addTitle, removeTitle, icon, formatName }) => {
  const [currentFormat, iconComponentFor] = useCellValues(currentFormat$, iconComponentFor$)
  const applyFormat = usePublisher(applyFormat$)
  const active = (currentFormat & format) !== 0

  return (
    <ToggleSingleGroupWithItem
      title={active ? removeTitle : addTitle}
      on={active}
      onValueChange={() => {
        applyFormat(formatName)
      }}
    >
      {iconComponentFor(icon)}
    </ToggleSingleGroupWithItem>
  )
}

